(121, 3, '@app.route(\"/\", methods=[\"GET\", \"POST\"])\r\ndef index():\r\n\r\n    result = None\r\n    text = \"\"\r\n    scores = {}\r\n\r\n    positif_score = 0\r\n    negatif_score = 0\r\n    netral_score = 0\r\n\r\n    not_ready = False\r\n\r\n    if request.method == \"POST\":\r\n        text = request.form.get(\"text\", \"\").strip()\r\n\r\n        if text:\r\n            # =======================================================\r\n            # PROSES PENUH MURNI MENGGUNAKAN MACHINE LEARNING & AI\r\n            # =======================================================\r\n            # 1. Jalankan preprocessing (termasuk deteksi kata negasi/tanda hubung otomatis)\r\n            tokens = preprocess_text(text)\r\n            \r\n            # 2. Ambil data prediksi murni dari kalkulasi gabungan Naïve Bayes + Lexicon\r\n            result_data = predict(tokens)\r\n            result = result_data.get(\"label\", \"Netral\")\r\n            scores = result_data.get(\"scores\", {})\r\n\r\n            # 3. Ekstrak skor probabilitas asli untuk visualisasi bar pada frontend\r\n            positif_score = scores.get(\"positif\", 0)\r\n            negatif_score = scores.get(\"negatif\", 0)\r\n            netral_score = scores.get(\"netral\", 0)\r\n\r\n            # =======================================================\r\n            # CEK VALIDASI LABEL\r\n            # =======================================================\r\n            if str(result).lower() not in (\"positif\", \"negatif\", \"netral\"):\r\n                not_ready = True\r\n                result = None\r\n                return render_template(\r\n                    \"public/index.html\",\r\n                    result=None,\r\n                    text=text,\r\n                    scores={},\r\n                    positif_score=0,\r\n                    negatif_score=0,\r\n                    netral_score=0,\r\n                    not_ready=True,\r\n                    role=session.get(\"role\")\r\n                )\r\n\r\n            # Format penulisan kapital huruf untuk kebutuhan Database\r\n            if str(result).lower() == \"positif\":\r\n                hasil_db = \"Positif\"\r\n            elif str(result).lower() == \"negatif\":\r\n                hasil_db = \"Negatif\"\r\n            else:\r\n                hasil_db = \"Netral\"\r\n\r\n            # =======================================================\r\n            # SIMPAN HISTORI KE DATABASE\r\n            # =======================================================\r\n            try:\r\n                conn = get_connection()\r\n                cursor = conn.cursor()\r\n                cursor.execute(\"\"\"\r\n                    INSERT INTO hasil_analisis (user_id, teks, hasil)\r\n                    VALUES (%s, %s, %s)\r\n                \"\"\", (\r\n                    session.get(\"user_id\"),\r\n                    text,\r\n                    hasil_db\r\n                ))\r\n                conn.commit()\r\n                print(\"Histori berhasil disimpan\")\r\n            except Exception as e:\r\n                print(f\"Error simpan histori: {e}\")\r\n            finally:\r\n                if \'cursor\' in locals() and cursor: cursor.close()\r\n                if \'conn\' in locals() and conn: conn.close()\r\n\r\n    return render_template(\r\n        \"public/index.html\",\r\n        result=result,\r\n        text=text,\r\n        scores=scores,\r\n        positif_score=positif_score,\r\n        negatif_score=negatif_score,\r\n        netral_score=netral_score,\r\n        not_ready=not_ready,\r\n        stats=get_landing_stats(),\r\n        role=session.get(\"role\")\r\n    )', 'Positif', '2026-06-21 15:51:14'),
